html:
{%- set cur = doc.currency -%}
{%- set company = frappe.get_cached_doc("Company", doc.company) -%}
{%- set mobile = doc.contact_mobile or frappe.db.get_value("Customer", doc.customer, "mobile_no") -%}
{%- set ratio = (doc.grand_total / doc.total) if doc.total else 1 -%}
<style>
	@page { margin: 2mm 3mm; }
	.print-format { padding: 0 !important; margin: 0 !important; max-width: 74mm !important; width: 74mm !important; min-height: 0 !important; }
	.apn { font-family: Arial, Helvetica, sans-serif; font-size: 9pt; color: #000; width: 74mm; line-height: 1.25; }
	.apn table { width: 100%; border-collapse: collapse; }
	.apn td { padding: 1px 0 !important; vertical-align: top; border: 0 !important; }
	.apn .c { text-align: center; }
	.apn .r { text-align: right; }
	.apn .b { font-weight: 700; }
	.apn .sm { font-size: 7.5pt; }
	.apn .hr { border-top: 1px dashed #000; margin: 3px 0; }
	.apn .big { font-size: 12pt; font-weight: 700; }
	.apn .name { font-size: 12pt; font-weight: 700; }
	.apn .box { border: 1px solid #000; padding: 2px 4px; margin: 3px 0; }
</style>
<div class="apn">
	<div class="c name">{{ company.company_name }}</div>
	{%- if company.phone_no %}<div class="c sm">{{ _("Ph") }}: {{ company.phone_no }}</div>{% endif %}
	<div class="hr"></div>
	<div class="c big">{{ _("APPROVAL NOTE") }}</div>
	<div class="c sm">{{ _("Goods on approval - not a bill") }}</div>
	{%- if doc.is_return %}<div class="c b">{{ _("RETURN") }} - {{ doc.return_against }}</div>{% endif %}
	<table class="sm">
		<tr><td>{{ _("No") }}: <b>{{ doc.name }}</b></td><td class="r">{{ frappe.utils.format_date(doc.posting_date) }} {{ (doc.posting_time|string)[:5] }}</td></tr>
		<tr><td colspan="2">{{ _("Customer") }}: <b>{{ doc.customer_name }}</b>{% if mobile %} ({{ mobile }}){% endif %}</td></tr>
		{%- if doc.custom_approved_by %}<tr><td colspan="2">{{ _("Approved by") }}: {{ frappe.utils.get_fullname(doc.custom_approved_by) }}</td></tr>{% endif %}
	</table>
	<div class="hr"></div>
	<table>
		{%- for i in doc.items %}
		<tr><td colspan="2" class="b">{{ i.item_name }}</td></tr>
		<tr class="sm"><td>{{ i.item_code }}{% if i.serial_no %} - {{ i.serial_no | replace("\n", ", ") }}{% endif %}</td><td></td></tr>
		<tr class="sm"><td>{{ (i.qty|abs) | int if i.qty == i.qty|int else i.qty|abs }} x {{ frappe.utils.fmt_money((i.amount / i.qty * ratio) if i.qty else 0, currency=cur) }}</td>
			<td class="r b">{{ frappe.utils.fmt_money((i.amount * ratio)|abs, currency=cur) }}</td></tr>
		{%- endfor %}
	</table>
	<div class="hr"></div>
	<table>
		<tr><td>{{ _("Pieces") }}: {{ (doc.total_qty|abs) | int if doc.total_qty == doc.total_qty|int else doc.total_qty|abs }}</td>
			<td class="r b">{{ _("Value") }} {{ frappe.utils.fmt_money(doc.grand_total|abs, currency=cur) }}</td></tr>
	</table>
	{%- if not doc.is_return %}
	<div class="box sm">{{ _("These goods are given on approval. Please return what you do not keep; the pieces you keep will be billed.") }}</div>
	{%- if doc.instructions %}<div class="sm">{{ _("Note") }}: {{ doc.instructions }}</div>{% endif %}
	<br><br>
	<table class="sm"><tr><td>{{ _("Customer signature") }}</td><td class="r">{{ _("For") }} {{ company.company_name }}</td></tr></table>
	{%- endif %}
</div>
